-- Nexora Food: additive platform schema. Original 001–003 retained unchanged.
set search_path=public,extensions;
create schema if not exists private;
revoke all on schema private from public;
grant usage on schema private to authenticated,anon;
create function private.nexora_is_admin() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.user_roles where user_id=auth.uid() and role in ('admin','super_admin'))$$;
create function private.nexora_is_super_admin() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.user_roles where user_id=auth.uid() and role='super_admin')$$;
create function private.nexora_member(r uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.restaurant_members where user_id=auth.uid() and restaurant_id=r)$$;
revoke all on function private.nexora_is_admin(),private.nexora_is_super_admin(),private.nexora_member(uuid) from public;
grant execute on function private.nexora_is_admin(),private.nexora_is_super_admin(),private.nexora_member(uuid) to authenticated,anon;
create table public.coupons(id uuid primary key default gen_random_uuid(),code extensions.citext unique not null,type text not null check(type in('percent','flat')),value integer not null check(value>0),max_discount_paise bigint not null check(max_discount_paise>=0),min_order_paise bigint not null default 0 check(min_order_paise>=0),starts_at timestamptz not null default now(),ends_at timestamptz not null,usage_limit_total integer not null default 1000,usage_limit_per_user integer not null default 1,restaurant_id uuid references public.restaurants(id),first_order_only boolean not null default false,is_active boolean not null default true,stackable boolean not null default false,created_at timestamptz default now(),check(ends_at>starts_at),check(type<>'percent' or value<=100));
create table public.orders(id uuid primary key default gen_random_uuid(),order_number text unique not null default ('NX-'||to_char(now(),'YYMMDD')||'-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,12))),user_id uuid not null references auth.users(id),restaurant_id uuid not null references public.restaurants(id),restaurant_name_snapshot text not null,address_snapshot jsonb not null,status public.order_status not null,payment_method public.payment_method not null,payment_status public.payment_status not null,items_subtotal_paise bigint not null check(items_subtotal_paise>=0),discount_coupon_paise bigint not null default 0 check(discount_coupon_paise>=0),discount_loyalty_paise bigint not null default 0 check(discount_loyalty_paise>=0),delivery_fee_paise bigint not null check(delivery_fee_paise>=0),packaging_paise bigint not null default 0 check(packaging_paise>=0),platform_fee_paise bigint not null default 0 check(platform_fee_paise>=0),tax_paise bigint not null check(tax_paise>=0),tip_paise bigint not null default 0 check(tip_paise>=0),total_paise bigint not null check(total_paise>0),currency text not null default 'INR' check(currency='INR'),points_redeemed integer not null default 0,points_earned integer not null default 0,special_instructions text,idempotency_key text not null,estimated_delivery_at timestamptz,placed_at timestamptz,accepted_at timestamptz,delivered_at timestamptz,cancelled_at timestamptz,cancel_reason text,cancelled_by uuid,is_demo boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(user_id,idempotency_key),check(total_paise=items_subtotal_paise-discount_coupon_paise-discount_loyalty_paise+delivery_fee_paise+packaging_paise+platform_fee_paise+tax_paise+tip_paise),check(discount_coupon_paise+discount_loyalty_paise<=items_subtotal_paise));
create index orders_user_time on public.orders(user_id,created_at desc);create index orders_rest_status on public.orders(restaurant_id,status);
create table public.order_items(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id),menu_item_id uuid references public.menu_items(id),name_snapshot text not null,unit_price_paise bigint not null check(unit_price_paise>=0),quantity integer not null check(quantity between 1 and 20),variant_snapshot jsonb,line_total_paise bigint not null check(line_total_paise>=0),is_veg boolean not null,instructions text,check(line_total_paise=unit_price_paise*quantity));
create index order_items_parent on public.order_items(order_id);
create table public.order_item_customizations(id uuid primary key default gen_random_uuid(),order_item_id uuid not null references public.order_items(id),group_name text not null,option_name text not null,price_paise bigint not null check(price_paise>=0));
create table public.order_status_history(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id),from_status public.order_status,to_status public.order_status not null,actor_id uuid,actor_role text,note text,created_at timestamptz not null default now());
create table public.payments(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id),provider text not null default 'razorpay',provider_order_id text unique,provider_payment_id text unique,amount_paise bigint not null check(amount_paise>0),status public.payment_status not null default 'pending',signature_verified boolean not null default false,raw_event_id text,created_at timestamptz not null default now());
create table public.refunds(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id),payment_id uuid not null references public.payments(id),amount_paise bigint not null check(amount_paise>0),reason text not null,status public.refund_status not null default 'requested',provider_refund_id text unique,requested_by uuid,created_at timestamptz not null default now());
create table public.webhook_events(id uuid primary key default gen_random_uuid(),provider text not null,event_id text not null,payload jsonb not null,processed_at timestamptz,status text not null default 'received',unique(provider,event_id));
create table public.idempotency_keys(key text not null,user_id uuid not null,scope text not null,request_hash text not null,response jsonb,created_at timestamptz default now(),expires_at timestamptz not null,primary key(user_id,scope,key));
create table public.coupon_redemptions(id uuid primary key default gen_random_uuid(),coupon_id uuid not null references public.coupons(id),user_id uuid not null references auth.users(id),order_id uuid not null unique references public.orders(id),discount_paise bigint not null check(discount_paise>=0),released_at timestamptz);
create table public.restaurant_reviews(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),restaurant_id uuid not null references public.restaurants(id),order_id uuid not null unique references public.orders(id),rating smallint not null check(rating between 1 and 5),body text check(length(body)<=2000),status text not null default 'visible' check(status in('visible','hidden','reported')),edited_until timestamptz not null default now()+interval '24 hours',created_at timestamptz not null default now());
create table public.food_item_reviews(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),menu_item_id uuid not null references public.menu_items(id),order_item_id uuid not null unique references public.order_items(id),rating smallint not null check(rating between 1 and 5),body text,status text not null default 'visible',created_at timestamptz default now());
create table public.review_reports(id uuid primary key default gen_random_uuid(),review_type text not null,review_id uuid not null,reporter_id uuid not null references auth.users(id),reason text not null,status text not null default 'open',resolved_by uuid,created_at timestamptz default now());
create table public.loyalty_accounts(user_id uuid primary key references auth.users(id),balance_points integer not null default 0 check(balance_points>=0),lifetime_points integer not null default 0,tier text not null default 'Bronze');
create table public.loyalty_ledger(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),type public.ledger_type not null,points integer not null check(points<>0),order_id uuid references public.orders(id),ref text unique,expires_at timestamptz,reason text,created_by uuid,created_at timestamptz not null default now());
create unique index loyalty_earn_once on public.loyalty_ledger(order_id) where type='earn';create unique index loyalty_reversal_once on public.loyalty_ledger(order_id) where type='reversal';
create table public.loyalty_tiers(name text primary key,min_lifetime_points integer not null check(min_lifetime_points>=0),benefits jsonb not null default '{}',is_active boolean not null default true);
create table public.device_tokens(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),token text not null unique,platform text not null,app_version text,last_seen_at timestamptz default now(),is_active boolean default true);
create table public.user_notifications(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),type text not null,title text not null,body text not null,data jsonb not null default '{}',order_id uuid references public.orders(id),read_at timestamptz,dedupe_key text unique,created_at timestamptz default now());
create table public.notification_templates(key text primary key,title text not null,body text not null,is_active boolean default true);
create table public.support_tickets(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),order_id uuid references public.orders(id),subject text not null check(length(subject) between 1 and 150),body text not null check(length(body) between 1 and 2000),status text not null default 'open' check(status in('open','pending','resolved','closed')),assigned_to uuid,priority text default 'normal',created_at timestamptz default now());
create table public.app_settings(key text primary key,value jsonb not null,updated_by uuid,updated_at timestamptz default now());
create table public.admin_audit_logs(id uuid primary key default gen_random_uuid(),actor_id uuid not null,action text not null,entity text not null,entity_id text,before jsonb,after jsonb,reason text not null,created_at timestamptz default now());
create table public.delivery_partners(user_id uuid primary key references auth.users(id),name text not null,phone text,restaurant_id uuid references public.restaurants(id),is_active boolean not null default true);
create table public.delivery_assignments(id uuid primary key default gen_random_uuid(),order_id uuid not null unique references public.orders(id),partner_id uuid not null references public.delivery_partners(user_id),assigned_by uuid not null,status text not null default 'assigned' check(status in('assigned','picked_up','delivered','failed')),assigned_at timestamptz default now(),picked_up_at timestamptz,delivered_at timestamptz);
create table public.restaurant_settlements(id uuid primary key default gen_random_uuid(),restaurant_id uuid not null references public.restaurants(id),period_start date not null,period_end date not null,gross_paise bigint not null,commission_paise bigint not null,tax_on_commission_paise bigint not null,refunds_paise bigint not null,net_payable_paise bigint not null,status text not null default 'draft' check(status in('draft','approved','paid')),paid_ref text,created_at timestamptz default now(),check(period_end>=period_start));
create table public.deletion_requests(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),requested_at timestamptz not null default now(),status text not null default 'requested' check(status in('requested','processing','completed','rejected')),notes text);
create unique index deletion_one_open on public.deletion_requests(user_id) where status in('requested','processing');
create table public.search_history(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),query text not null,created_at timestamptz default now());
create table private.cart_quotes(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),restaurant_id uuid not null,lines jsonb not null,address_id uuid not null,coupon text,points integer not null,totals jsonb not null,expires_at timestamptz not null default now()+interval '5 minutes',used_at timestamptz);
alter table public.user_addresses add column latitude numeric check(latitude between -90 and 90),add column longitude numeric check(longitude between -180 and 180);
-- Explicit grants are paired with deny-by-default RLS; privileged fields have no client UPDATE grant.
do $$declare t record;begin for t in select tablename from pg_tables where schemaname='public' loop execute format('alter table public.%I enable row level security',t.tablename);end loop;end$$;
alter table private.cart_quotes enable row level security;
revoke all on all tables in schema public from anon,authenticated;
grant select on all tables in schema public to authenticated;
grant select on public.restaurants,public.food_categories,public.restaurant_cuisines,public.menu_categories,public.menu_items,public.menu_item_variants,public.menu_addon_groups,public.menu_item_addons,public.restaurant_reviews,public.food_item_reviews,public.restaurant_hours to anon;
grant insert on public.support_tickets,public.device_tokens to authenticated;
grant update(read_at) on public.user_notifications to authenticated;
grant delete on public.device_tokens to authenticated;
create policy profiles_own_read on public.profiles for select to authenticated using(id=auth.uid() or private.nexora_is_admin());
create policy roles_own_read on public.user_roles for select to authenticated using(user_id=auth.uid() or private.nexora_is_super_admin());
create policy members_own_read on public.restaurant_members for select to authenticated using(user_id=auth.uid() or private.nexora_is_admin());
create policy addresses_own_read on public.user_addresses for select to authenticated using(user_id=auth.uid());
create policy restaurants_public_read on public.restaurants for select to anon,authenticated using(status='active' or private.nexora_member(id) or private.nexora_is_admin());
create policy hours_public_read on public.restaurant_hours for select to anon,authenticated using(exists(select 1 from public.restaurants r where r.id=restaurant_id and r.status='active') or private.nexora_member(restaurant_id) or private.nexora_is_admin());
create policy categories_public_read on public.food_categories for select to anon,authenticated using(is_active or private.nexora_is_admin());
create policy cuisines_public_read on public.restaurant_cuisines for select to anon,authenticated using(exists(select 1 from public.restaurants r where r.id=restaurant_id and r.status='active') or private.nexora_is_admin());
create policy menucategories_public_read on public.menu_categories for select to anon,authenticated using((is_active and exists(select 1 from public.restaurants r where r.id=restaurant_id and r.status='active')) or private.nexora_member(restaurant_id) or private.nexora_is_admin());
create policy menu_public_read on public.menu_items for select to anon,authenticated using((deleted_at is null and exists(select 1 from public.restaurants r where r.id=restaurant_id and r.status='active')) or private.nexora_member(restaurant_id) or private.nexora_is_admin());
create policy variants_public_read on public.menu_item_variants for select to anon,authenticated using(exists(select 1 from public.menu_items i where i.id=item_id));
create policy addon_groups_public_read on public.menu_addon_groups for select to anon,authenticated using(exists(select 1 from public.menu_items i where i.id=item_id));
create policy addons_public_read on public.menu_item_addons for select to anon,authenticated using(exists(select 1 from public.menu_addon_groups g where g.id=group_id));
create policy favorites_own_read on public.favorites for select to authenticated using(user_id=auth.uid());
create policy orders_authorized_read on public.orders for select to authenticated using(user_id=auth.uid() or private.nexora_member(restaurant_id) or private.nexora_is_admin() or exists(select 1 from public.delivery_assignments a where a.order_id=orders.id and a.partner_id=auth.uid()));
create policy assignments_read on public.delivery_assignments for select to authenticated using(partner_id=auth.uid() or private.nexora_is_admin());
create policy partners_read on public.delivery_partners for select to authenticated using(user_id=auth.uid() or private.nexora_is_admin());
create policy orderitems_read on public.order_items for select to authenticated using(exists(select 1 from public.orders o where o.id=order_id));
create policy customizations_read on public.order_item_customizations for select to authenticated using(exists(select 1 from public.order_items i where i.id=order_item_id));
create policy history_read on public.order_status_history for select to authenticated using(exists(select 1 from public.orders o where o.id=order_id));
create policy reviews_visible_read on public.restaurant_reviews for select to anon,authenticated using(status='visible' or user_id=auth.uid() or private.nexora_is_admin());
create policy itemreviews_visible_read on public.food_item_reviews for select to anon,authenticated using(status='visible' or user_id=auth.uid() or private.nexora_is_admin());
create policy coupons_read on public.coupons for select to authenticated using((is_active and ends_at>now()) or private.nexora_is_admin());
create policy loyalty_own_read on public.loyalty_accounts for select to authenticated using(user_id=auth.uid() or private.nexora_is_admin());
create policy ledger_own_read on public.loyalty_ledger for select to authenticated using(user_id=auth.uid() or private.nexora_is_admin());
create policy tiers_read on public.loyalty_tiers for select to authenticated using(is_active);
create policy tokens_own_read on public.device_tokens for select to authenticated using(user_id=auth.uid());
create policy tokens_own_insert on public.device_tokens for insert to authenticated with check(user_id=auth.uid());
create policy tokens_own_delete on public.device_tokens for delete to authenticated using(user_id=auth.uid());
create policy notifications_own_read on public.user_notifications for select to authenticated using(user_id=auth.uid());
create policy notifications_own_update on public.user_notifications for update to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy support_own_read on public.support_tickets for select to authenticated using(user_id=auth.uid() or private.nexora_is_admin());
create policy support_own_insert on public.support_tickets for insert to authenticated with check(user_id=auth.uid() and status='open' and assigned_to is null and (order_id is null or exists(select 1 from public.orders o where o.id=order_id and o.user_id=auth.uid())));
create policy settings_admin_read on public.app_settings for select to authenticated using(private.nexora_is_admin());
create policy audit_admin_read on public.admin_audit_logs for select to authenticated using(private.nexora_is_admin());
create policy settlements_authorized_read on public.restaurant_settlements for select to authenticated using(private.nexora_is_admin() or private.nexora_member(restaurant_id));
create policy deletion_authorized_read on public.deletion_requests for select to authenticated using(user_id=auth.uid() or private.nexora_is_super_admin());
-- Profiles/roles cannot be promoted through editable auth metadata.
create function private.nexora_new_user() returns trigger language plpgsql security definer set search_path=public as $$begin insert into public.profiles(id,phone,email,full_name)values(new.id,new.phone,new.email,'')on conflict(id)do nothing;insert into public.user_roles(user_id,role)values(new.id,'customer')on conflict do nothing;insert into public.loyalty_accounts(user_id)values(new.id)on conflict do nothing;return new;end$$;
create trigger nexora_new_user after insert on auth.users for each row execute function private.nexora_new_user();
create function private.nexora_ledger_balance() returns trigger language plpgsql security definer set search_path=public as $$begin update public.loyalty_accounts set balance_points=balance_points+new.points,lifetime_points=lifetime_points+case when new.type='earn' then new.points else 0 end where user_id=new.user_id;return new;end$$;
create trigger nexora_ledger_balance after insert on public.loyalty_ledger for each row execute function private.nexora_ledger_balance();
create function public.nexora_save_profile(p_name text,p_email text) returns void language plpgsql security definer set search_path=public as $$begin if auth.uid() is null then raise exception 'Sign in required';end if;if length(trim(p_name)) not between 1 and 120 then raise exception 'Enter a name between 1 and 120 characters';end if;if coalesce(p_email,'')<>'' and p_email !~ '^[^ @]+@[^ @]+\.[^ @]+$' then raise exception 'Invalid email';end if;update public.profiles set full_name=trim(p_name),email=nullif(trim(p_email),'') where id=auth.uid();end$$;
create function public.nexora_save_address(p_address jsonb) returns uuid language plpgsql security definer set search_path=public,extensions as $$declare aid uuid:=gen_random_uuid();lat numeric:=(p_address->>'latitude')::numeric;lng numeric:=(p_address->>'longitude')::numeric;begin if auth.uid() is null then raise exception 'Sign in required';end if;if lat not between -90 and 90 or lng not between -180 and 180 then raise exception 'Invalid coordinates';end if;insert into public.user_addresses(id,user_id,type,line1,locality,city,state,pincode,latitude,longitude,location,is_default)values(aid,auth.uid(),p_address->>'type',trim(p_address->>'line1'),p_address->>'locality',p_address->>'city',p_address->>'state',p_address->>'pincode',lat,lng,extensions.ST_SetSRID(extensions.ST_MakePoint(lng,lat),4326)::extensions.geography,not exists(select 1 from public.user_addresses where user_id=auth.uid() and deleted_at is null));return aid;end$$;
create function public.nexora_toggle_favorite(p_restaurant uuid) returns boolean language plpgsql security definer set search_path=public as $$begin if auth.uid() is null then raise exception 'Sign in required';end if;delete from public.favorites where user_id=auth.uid() and restaurant_id=p_restaurant;if found then return false;end if;insert into public.favorites(user_id,restaurant_id)values(auth.uid(),p_restaurant)on conflict do nothing;return true;end$$;
create function private.nexora_setting(k text) returns jsonb language sql stable security definer set search_path=public as $$select value from public.app_settings where key=k$$;
create function private.nexora_compute(p_restaurant uuid,p_lines jsonb,p_address uuid,p_coupon text,p_points integer) returns jsonb language plpgsql security definer set search_path=public,extensions as $$
declare r public.restaurants;a public.user_addresses;i public.menu_items;l jsonb;v public.menu_item_variants;g public.menu_addon_groups;ad public.menu_item_addons;c public.coupons;subtotal bigint:=0;unit bigint;qty integer;discount bigint:=0;loyalty bigint:=0;fee bigint;taxbps integer;tax bigint;balance integer;chosen integer;ts timestamp:=now() at time zone 'Asia/Kolkata';valid_hours boolean;begin
 if auth.uid() is null then raise exception 'Sign in required';end if;
 if exists(select 1 from public.profiles where id=auth.uid() and is_blocked)then raise exception 'This account cannot place orders';end if;
 if jsonb_typeof(p_lines)<>'array' or jsonb_array_length(p_lines) not between 1 and 100 then raise exception 'Invalid cart';end if;
 if p_points<0 or p_points%100<>0 then raise exception 'Redeem points in multiples of 100';end if;
 select * into r from public.restaurants where id=p_restaurant;
 if not found or r.status<>'active' or r.is_temporarily_closed or r.is_demo then raise exception 'Restaurant is unavailable';end if;
 select * into a from public.user_addresses where id=p_address and user_id=auth.uid() and deleted_at is null;
 if not found or a.location is null then raise exception 'Choose a valid delivery address';end if;
 if not exists(select 1 from public.restaurant_delivery_zones z where z.is_active and(z.restaurant_id is null or z.restaurant_id=r.id)and((z.polygon is not null and extensions.ST_Covers(z.polygon::extensions.geometry,a.location::extensions.geometry))or(z.center is not null and extensions.ST_DWithin(z.center,a.location,z.radius_m))))then raise exception 'We do not deliver to this address yet';end if;
 select exists(select 1 from public.restaurant_hours h where h.restaurant_id=r.id and not h.is_closed and((h.weekday=extract(dow from ts) and h.closes>h.opens and ts::time>=h.opens and ts::time<h.closes)or(h.closes<h.opens and((h.weekday=extract(dow from ts)and ts::time>=h.opens)or(h.weekday=extract(dow from ts-interval '1 day')and ts::time<h.closes)))))into valid_hours;
 if not valid_hours then raise exception 'Restaurant is closed or business hours are not configured';end if;
 for l in select value from jsonb_array_elements(p_lines) loop
 qty:=(l->>'quantity')::integer;if qty not between 1 and 20 then raise exception 'Quantity must be between 1 and 20';end if;
 select * into i from public.menu_items where id=(l->>'item_id')::uuid and restaurant_id=r.id and is_available and deleted_at is null and not is_demo for share;if not found then raise exception 'A selected item is unavailable';end if;unit:=i.price_paise;
 if l->>'variant_id' is not null then select * into v from public.menu_item_variants where id=(l->>'variant_id')::uuid and item_id=i.id and is_available;if not found then raise exception 'Variant unavailable';end if;unit:=unit+v.price_delta_paise;
 elsif exists(select 1 from public.menu_item_variants where item_id=i.id and is_available)then raise exception 'Choose a dish variant';end if;
 if jsonb_array_length(coalesce(l->'addon_ids','[]'))>50 then raise exception 'Too many add-ons';end if;
 if (select count(*) from jsonb_array_elements_text(coalesce(l->'addon_ids','[]')))<>(select count(distinct value)from jsonb_array_elements_text(coalesce(l->'addon_ids','[]')))then raise exception 'Duplicate add-on';end if;
 for ad in select aa.* from public.menu_item_addons aa where aa.id in(select value::uuid from jsonb_array_elements_text(coalesce(l->'addon_ids','[]')))loop if not ad.is_available or not exists(select 1 from public.menu_addon_groups gg where gg.id=ad.group_id and gg.item_id=i.id)then raise exception 'Invalid add-on';end if;unit:=unit+ad.price_paise;end loop;
 if (select count(*)from public.menu_item_addons where id in(select value::uuid from jsonb_array_elements_text(coalesce(l->'addon_ids','[]'))))<>jsonb_array_length(coalesce(l->'addon_ids','[]'))then raise exception 'Unknown add-on';end if;
 for g in select * from public.menu_addon_groups where item_id=i.id loop select count(*)into chosen from public.menu_item_addons where group_id=g.id and id in(select value::uuid from jsonb_array_elements_text(coalesce(l->'addon_ids','[]')));if chosen<g.min_select or chosen>g.max_select then raise exception 'Add-on selection invalid for %',g.name;end if;end loop;
 subtotal:=subtotal+unit*qty;
 end loop;
 if subtotal<r.min_order_paise then raise exception 'Minimum order not met';end if;
 if coalesce(p_coupon,'')<>'' then select * into c from public.coupons where code=p_coupon::extensions.citext for update;if not found or not c.is_active or now()<c.starts_at or now()>=c.ends_at or subtotal<c.min_order_paise or(c.restaurant_id is not null and c.restaurant_id<>r.id)then raise exception 'Coupon is not eligible';end if;
 if (select count(*)from public.coupon_redemptions where coupon_id=c.id and released_at is null)>=c.usage_limit_total or(select count(*)from public.coupon_redemptions where coupon_id=c.id and user_id=auth.uid() and released_at is null)>=c.usage_limit_per_user then raise exception 'Coupon usage limit reached';end if;
 if c.first_order_only and exists(select 1 from public.orders where user_id=auth.uid() and status not in('cancelled','rejected'))then raise exception 'Coupon is for first orders only';end if;
 discount:=least(subtotal,c.max_discount_paise,case when c.type='percent' then floor(subtotal::numeric*c.value/100)::bigint else c.value end);end if;
 select balance_points into balance from public.loyalty_accounts where user_id=auth.uid() for update;
 if p_points>coalesce(balance,0)then raise exception 'Insufficient reward points';end if;
 loyalty:=p_points::bigint*10;if loyalty>floor(subtotal::numeric*.2) or loyalty>subtotal-discount then raise exception 'Reward redemption exceeds order limit';end if;
 fee:=coalesce(r.delivery_fee_override_paise,(private.nexora_setting('delivery.flat_paise')#>>'{}')::bigint);taxbps:=(private.nexora_setting('tax.bps')#>>'{}')::integer;
 if fee is null or taxbps is null then raise exception 'Delivery fees and reviewed tax settings must be configured';end if;
 tax:=floor(((subtotal-discount-loyalty)::numeric*taxbps+5000)/10000)::bigint;
 return jsonb_build_object('items_subtotal_paise',subtotal,'discount_coupon_paise',discount,'discount_loyalty_paise',loyalty,'delivery_fee_paise',fee,'packaging_paise',0,'platform_fee_paise',0,'tax_paise',tax,'total_paise',subtotal-discount-loyalty+fee+tax,'points_redeemed',p_points);
end$$;
create function public.nexora_quote_cart(p_restaurant uuid,p_lines jsonb,p_address uuid,p_coupon text default null,p_points integer default 0)returns jsonb language plpgsql security definer set search_path=public as $$declare totals jsonb;q uuid;expiry timestamptz;begin totals:=private.nexora_compute(p_restaurant,p_lines,p_address,p_coupon,p_points);insert into private.cart_quotes(user_id,restaurant_id,lines,address_id,coupon,points,totals)values(auth.uid(),p_restaurant,p_lines,p_address,p_coupon,p_points,totals)returning id,expires_at into q,expiry;return totals||jsonb_build_object('quote_id',q,'expires_at',expiry);end$$;
create function public.nexora_place_order(p_restaurant uuid,p_lines jsonb,p_address uuid,p_coupon text,p_points integer,p_key text,p_method text,p_quote uuid)returns jsonb language plpgsql security definer set search_path=public,extensions as $$
declare q private.cart_quotes;totals jsonb;o public.orders;line jsonb;i public.menu_items;unit bigint;v jsonb;oi uuid;hash text;a public.user_addresses;begin
 if auth.uid() is null then raise exception 'Sign in required';end if;if length(p_key)not between 8 and 100 then raise exception 'Invalid checkout key';end if;
 perform pg_advisory_xact_lock(hashtextextended(auth.uid()::text||p_key,0));
 hash:=encode(extensions.digest(jsonb_build_object('restaurant',p_restaurant,'lines',p_lines,'address',p_address,'coupon',p_coupon,'points',p_points,'method',p_method)::text,'sha256'),'hex');
 select * into o from public.orders where user_id=auth.uid()and idempotency_key=p_key;
 if found then if not exists(select 1 from public.idempotency_keys where user_id=auth.uid()and key=p_key and scope='checkout' and request_hash=hash)then raise exception 'Checkout key reused with different contents';end if;return jsonb_build_object('id',o.id,'order_number',o.order_number);end if;
 select * into q from private.cart_quotes where id=p_quote and user_id=auth.uid() for update;
 if not found or q.used_at is not null or q.expires_at<now() or q.restaurant_id<>p_restaurant or q.lines<>p_lines or q.address_id<>p_address or q.points<>p_points or q.coupon is distinct from p_coupon then raise exception 'Quote expired or cart changed. Review prices again';end if;
 totals:=private.nexora_compute(p_restaurant,p_lines,p_address,p_coupon,p_points);if totals<>q.totals then raise exception 'Prices were updated. Review your cart';end if;
 if p_method not in('cod','online') then raise exception 'Invalid payment method';end if;
 if p_method='cod' and (coalesce((private.nexora_setting('cod.enabled')#>>'{}')::boolean,false)=false or(totals->>'total_paise')::bigint>coalesce((private.nexora_setting('cod.max_paise')#>>'{}')::bigint,0))then raise exception 'Cash on delivery is unavailable for this order';end if;
 if p_method='online' and not coalesce((private.nexora_setting('payments.online_enabled')#>>'{}')::boolean,false)then raise exception 'Online payment setup pending';end if;
 select * into a from public.user_addresses where id=p_address and user_id=auth.uid();
 insert into public.orders(user_id,restaurant_id,restaurant_name_snapshot,address_snapshot,status,payment_method,payment_status,items_subtotal_paise,discount_coupon_paise,discount_loyalty_paise,delivery_fee_paise,tax_paise,total_paise,points_redeemed,idempotency_key,placed_at)values(auth.uid(),p_restaurant,(select name from public.restaurants where id=p_restaurant),to_jsonb(a)-'user_id'-'location',case when p_method='cod' then 'placed'::public.order_status else 'pending_payment'::public.order_status end,p_method::public.payment_method,case when p_method='cod' then 'cod_pending'::public.payment_status else 'pending'::public.payment_status end,(totals->>'items_subtotal_paise')::bigint,(totals->>'discount_coupon_paise')::bigint,(totals->>'discount_loyalty_paise')::bigint,(totals->>'delivery_fee_paise')::bigint,(totals->>'tax_paise')::bigint,(totals->>'total_paise')::bigint,p_points,p_key,case when p_method='cod' then now()end)returning * into o;
 for line in select value from jsonb_array_elements(p_lines)loop select * into i from public.menu_items where id=(line->>'item_id')::uuid;unit:=i.price_paise;v:=null;
 if line->>'variant_id' is not null then select jsonb_build_object('name',name,'price_delta_paise',price_delta_paise),i.price_paise+price_delta_paise into v,unit from public.menu_item_variants where id=(line->>'variant_id')::uuid;end if;
 unit:=unit+coalesce((select sum(price_paise)from public.menu_item_addons where id in(select value::uuid from jsonb_array_elements_text(coalesce(line->'addon_ids','[]')))),0);
 insert into public.order_items(order_id,menu_item_id,name_snapshot,unit_price_paise,quantity,variant_snapshot,line_total_paise,is_veg,instructions)values(o.id,i.id,i.name,unit,(line->>'quantity')::integer,v,unit*(line->>'quantity')::integer,i.is_veg,left(line->>'instructions',300))returning id into oi;
 insert into public.order_item_customizations(order_item_id,group_name,option_name,price_paise)select oi,g.name,ad.name,ad.price_paise from public.menu_item_addons ad join public.menu_addon_groups g on g.id=ad.group_id where ad.id in(select value::uuid from jsonb_array_elements_text(coalesce(line->'addon_ids','[]')));
 end loop;
 if p_points>0 then insert into public.loyalty_ledger(user_id,type,points,order_id,ref)values(auth.uid(),'redeem',-p_points,o.id,'redeem:'||o.id);end if;
 if coalesce(p_coupon,'')<>''then insert into public.coupon_redemptions(coupon_id,user_id,order_id,discount_paise)select id,auth.uid(),o.id,o.discount_coupon_paise from public.coupons where code=p_coupon::extensions.citext;end if;
 update private.cart_quotes set used_at=now()where id=q.id;
 insert into public.order_status_history(order_id,to_status,actor_id,actor_role)values(o.id,o.status,auth.uid(),'customer');
 insert into public.idempotency_keys(key,user_id,scope,request_hash,response,expires_at)values(p_key,auth.uid(),'checkout',hash,jsonb_build_object('id',o.id,'order_number',o.order_number),now()+interval '30 days');
 return jsonb_build_object('id',o.id,'order_number',o.order_number);
end$$;
create function public.nexora_transition_order(p_order uuid,p_to text,p_reason text default null)returns void language plpgsql security definer set search_path=public as $$
declare o public.orders;admin boolean:=private.nexora_is_admin();owner boolean;customer boolean;rider boolean;allowed boolean:=false;earn integer;begin
 if auth.uid() is null then raise exception 'Sign in required';end if;select * into o from public.orders where id=p_order for update;if not found then raise exception 'Order not found';end if;
 owner:=private.nexora_member(o.restaurant_id);customer:=o.user_id=auth.uid();rider:=exists(select 1 from public.delivery_assignments where order_id=o.id and partner_id=auth.uid());if not(admin or owner or customer or rider)then raise exception 'Access denied';end if;
 if o.status::text=p_to then return;end if;
 allowed:=(o.status='placed'and p_to in('confirmed','rejected')and(owner or admin)and now()<o.created_at+interval '5 minutes')or(o.status='confirmed'and p_to='preparing'and(owner or admin))or(o.status='preparing'and p_to='ready_for_pickup'and(owner or admin))or(o.status='ready_for_pickup'and p_to='out_for_delivery'and(owner or admin or rider)and exists(select 1 from public.delivery_assignments where order_id=o.id))or(o.status='out_for_delivery'and p_to='delivered'and(admin or rider))or(o.status in('pending_payment','placed','confirmed')and p_to='cancelled'and(customer or admin))or(o.status in('preparing','ready_for_pickup','out_for_delivery')and p_to='cancelled'and admin);
 if not allowed then raise exception 'This order status change is not allowed';end if;
 if p_to in('cancelled','rejected')and length(trim(coalesce(p_reason,'')))<3 then raise exception 'Reason is required';end if;
 update public.orders set status=p_to::public.order_status,accepted_at=case when p_to='confirmed'then now()else accepted_at end,delivered_at=case when p_to='delivered'then now()else delivered_at end,cancelled_at=case when p_to in('cancelled','rejected')then now()else cancelled_at end,cancel_reason=case when p_to in('cancelled','rejected')then p_reason else cancel_reason end,cancelled_by=case when p_to in('cancelled','rejected')then auth.uid()else cancelled_by end,payment_status=case when p_to='delivered'and payment_method='cod'then 'cod_collected'::public.payment_status when p_to in('cancelled','rejected')and payment_status='paid'then 'refund_pending'::public.payment_status else payment_status end,updated_at=now()where id=o.id;
 insert into public.order_status_history(order_id,from_status,to_status,actor_id,actor_role,note)values(o.id,o.status,p_to::public.order_status,auth.uid(),case when admin then 'admin' when owner then 'restaurant' when rider then 'rider' else 'customer' end,p_reason);
 if p_to in('cancelled','rejected')then
 if o.points_redeemed>0 then insert into public.loyalty_ledger(user_id,type,points,order_id,ref,reason)values(o.user_id,'adjustment',o.points_redeemed,o.id,'restore:'||o.id,'Order cancelled')on conflict(ref)do nothing;end if;
 update public.coupon_redemptions set released_at=now()where order_id=o.id;
 if o.payment_status='paid'then insert into public.refunds(order_id,payment_id,amount_paise,reason,requested_by)select o.id,id,o.total_paise,p_reason,auth.uid()from public.payments where order_id=o.id and status='paid';end if;
 end if;
 if p_to='delivered'then earn:=floor((o.items_subtotal_paise-o.discount_coupon_paise-o.discount_loyalty_paise)::numeric/coalesce((private.nexora_setting('loyalty.earn_per_paise')#>>'{}')::bigint,10000));if earn>0 then insert into public.loyalty_ledger(user_id,type,points,order_id,ref,expires_at)values(o.user_id,'earn',earn,o.id,'earn:'||o.id,now()+interval '365 days')on conflict do nothing;update public.orders set points_earned=earn where id=o.id;end if;end if;
 insert into public.user_notifications(user_id,type,title,body,order_id,dedupe_key)values(o.user_id,'order','Order update','Your order status changed. Open Nexora Food for details.',o.id,o.id||':'||p_to)on conflict do nothing;
 if admin then insert into public.admin_audit_logs(actor_id,action,entity,entity_id,before,after,reason)values(auth.uid(),'order-transition','orders',o.id::text,jsonb_build_object('status',o.status),jsonb_build_object('status',p_to),coalesce(p_reason,'Order progression'));end if;
end$$;
create function public.nexora_loyalty_summary()returns jsonb language sql stable security definer set search_path=public as $$select to_jsonb(a) from public.loyalty_accounts a where user_id=auth.uid()$$;
create function public.nexora_request_deletion()returns uuid language plpgsql security definer set search_path=public as $$declare rid uuid;begin if auth.uid() is null then raise exception 'Sign in required';end if;insert into public.deletion_requests(user_id)values(auth.uid())on conflict(user_id)where status in('requested','processing')do update set notes=public.deletion_requests.notes returning id into rid;update public.profiles set deletion_requested_at=now(),marketing_opt_in=false where id=auth.uid();return rid;end$$;
create function public.nexora_save_menu_item(p_item jsonb)returns uuid language plpgsql security definer set search_path=public as $$declare rid uuid:=(p_item->>'restaurant_id')::uuid;iid uuid:=coalesce((p_item->>'id')::uuid,gen_random_uuid());begin if auth.uid()is null or not(private.nexora_member(rid)or private.nexora_is_admin())then raise exception 'Access denied';end if;if exists(select 1 from public.menu_items where id=iid and restaurant_id<>rid)then raise exception 'Cannot move another restaurant item';end if;if coalesce(p_item->>'image_url','')<>''and(p_item->>'image_url'!~ '^https?://'or length(p_item->>'image_url')>2000)then raise exception 'Invalid image URL';end if;insert into public.menu_items(id,restaurant_id,name,description,price_paise,is_veg,is_available,is_bestseller,image_url)values(iid,rid,trim(p_item->>'name'),p_item->>'description',(p_item->>'price_paise')::bigint,(p_item->>'is_veg')::boolean,(p_item->>'is_available')::boolean,coalesce((p_item->>'is_bestseller')::boolean,false),nullif(p_item->>'image_url',''))on conflict(id)do update set name=excluded.name,description=excluded.description,price_paise=excluded.price_paise,is_veg=excluded.is_veg,is_available=excluded.is_available,image_url=excluded.image_url;return iid;end$$;
create function public.nexora_save_restaurant_profile(p_restaurant uuid,p_changes jsonb)returns void language plpgsql security definer set search_path=public as $$begin if auth.uid()is null or not(private.nexora_member(p_restaurant)or private.nexora_is_admin())then raise exception 'Access denied';end if;update public.restaurants set description=left(p_changes->>'description',2000),prep_time_min=(p_changes->>'prep_time_min')::integer,is_temporarily_closed=(p_changes->>'is_temporarily_closed')::boolean,phone=left(p_changes->>'phone',30)where id=p_restaurant;end$$;
create function public.nexora_admin_restaurant_status(p_restaurant uuid,p_status text,p_reason text)returns void language plpgsql security definer set search_path=public as $$begin if not private.nexora_is_admin()then raise exception 'Admin access required';end if;if length(trim(p_reason))<3 or p_reason is null then raise exception 'Reason required';end if;update public.restaurants set status=p_status where id=p_restaurant;if not found then raise exception 'Restaurant not found';end if;insert into public.admin_audit_logs(actor_id,action,entity,entity_id,after,reason)values(auth.uid(),'restaurant-status','restaurants',p_restaurant::text,jsonb_build_object('status',p_status),p_reason);end$$;
create function public.nexora_admin_create_restaurant(p_data jsonb)returns uuid language plpgsql security definer set search_path=public,extensions as $$declare rid uuid;begin if not private.nexora_is_admin()then raise exception 'Admin access required';end if;if p_data->>'slug' !~ '^[a-z0-9]+(-[a-z0-9]+)*$'then raise exception 'Invalid URL slug';end if;insert into public.restaurants(name,slug,address,city,location)values(p_data->>'name',p_data->>'slug',p_data->>'address',p_data->>'city',extensions.ST_SetSRID(extensions.ST_MakePoint((p_data->>'longitude')::numeric,(p_data->>'latitude')::numeric),4326)::extensions.geography)returning id into rid;if nullif(p_data->>'owner_id','')is not null then insert into public.restaurant_members(restaurant_id,user_id,role)values(rid,(p_data->>'owner_id')::uuid,'owner');end if;insert into public.admin_audit_logs(actor_id,action,entity,entity_id,after,reason)values(auth.uid(),'create','restaurants',rid::text,p_data-'owner_id','New restaurant onboarding');return rid;end$$;
create function public.nexora_admin_coupon(p_data jsonb)returns uuid language plpgsql security definer set search_path=public as $$declare cid uuid;begin if not private.nexora_is_admin()then raise exception 'Admin access required';end if;insert into public.coupons(code,type,value,min_order_paise,max_discount_paise,ends_at)values(p_data->>'code','percent',(p_data->>'percent')::integer,(p_data->>'min_order_paise')::bigint,(p_data->>'max_discount_paise')::bigint,(p_data->>'ends_at')::timestamptz)returning id into cid;insert into public.admin_audit_logs(actor_id,action,entity,entity_id,after,reason)values(auth.uid(),'create','coupons',cid::text,p_data,'New promotion');return cid;end$$;
create function public.nexora_admin_setting(p_key text,p_value jsonb,p_reason text)returns void language plpgsql security definer set search_path=public as $$begin if not private.nexora_is_super_admin()then raise exception 'Super Admin access required';end if;if length(trim(coalesce(p_reason,'')))<3 then raise exception 'Reason required';end if;if p_key not in('delivery.flat_paise','cod.enabled','cod.max_paise','loyalty.earn_per_paise','tax.bps','payments.online_enabled')then raise exception 'Unsupported setting';end if;if p_key in('cod.enabled','payments.online_enabled')and jsonb_typeof(p_value)<>'boolean'then raise exception 'Expected boolean';end if;if p_key not in('cod.enabled','payments.online_enabled')and(jsonb_typeof(p_value)<>'number' or(p_value#>>'{}')!~ '^[0-9]+$'or(p_value#>>'{}')::numeric>100000000)then raise exception 'Expected nonnegative integer';end if;if p_key='tax.bps'and(p_value#>>'{}')::integer>10000 then raise exception 'Invalid tax rate';end if;if p_key='loyalty.earn_per_paise'and(p_value#>>'{}')::bigint<1 then raise exception 'Earn divisor must be positive';end if;insert into public.app_settings(key,value,updated_by)values(p_key,p_value,auth.uid())on conflict(key)do update set value=excluded.value,updated_by=excluded.updated_by,updated_at=now();insert into public.admin_audit_logs(actor_id,action,entity,entity_id,after,reason)values(auth.uid(),'update','app_settings',p_key,p_value,p_reason);end$$;
create function public.nexora_admin_assign_rider(p_order uuid,p_rider uuid,p_reason text)returns void language plpgsql security definer set search_path=public as $$begin if not private.nexora_is_admin()then raise exception 'Admin required';end if;if length(coalesce(p_reason,''))<3 then raise exception 'Reason required';end if;if not exists(select 1 from public.delivery_partners where user_id=p_rider and is_active)then raise exception 'Rider unavailable';end if;insert into public.delivery_assignments(order_id,partner_id,assigned_by)values(p_order,p_rider,auth.uid())on conflict(order_id)do update set partner_id=excluded.partner_id,assigned_by=excluded.assigned_by;insert into public.admin_audit_logs(actor_id,action,entity,entity_id,after,reason)values(auth.uid(),'assign-rider','orders',p_order::text,jsonb_build_object('rider',p_rider),p_reason);end$$;
-- All public RPCs require authenticated JWT. Internal helpers and provider verification stay private.
do $$declare f record;begin for f in select p.oid::regprocedure as signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname like 'nexora_%'loop execute format('revoke all on function %s from public,anon',f.signature);execute format('grant execute on function %s to authenticated',f.signature);end loop;end$$;
revoke all on function private.nexora_compute(uuid,jsonb,uuid,text,integer),private.nexora_setting(text),private.nexora_new_user(),private.nexora_ledger_balance() from public,anon,authenticated;
-- Enable realtime for authorized order rows only.
do $$begin if exists(select 1 from pg_publication where pubname='supabase_realtime')and not exists(select 1 from pg_publication_tables where pubname='supabase_realtime'and tablename='orders')then alter publication supabase_realtime add table public.orders;end if;end$$;
